    printf("PPEXCL = %d\n", PPEXCL);
    printf("PPDATADIR = %d\n", PPDATADIR);
    printf("PPNEGOT = %d\n", PPNEGOT);
    printf("PPWCTLONIRQ = %d\n", PPWCTLONIRQ);
    printf("PPCLRIRQ = %d\n", PPCLRIRQ);
    printf("PPSETPHASE = %d\n", PPSETPHASE);
    printf("PPGETTIME = %d\n", PPGETTIME);
    printf("PPSETTIME = %d\n", PPSETTIME);
    printf("PPGETMODES = %d\n", PPGETMODES);
    printf("PPGETMODE = %d\n", PPGETMODE);
    printf("PPGETPHASE = %d\n", PPGETPHASE);
    printf("PPGETFLAGS = %d\n", PPGETFLAGS);
    printf("PPSETFLAGS = %d\n", PPSETFLAGS);

    printf("\nPP_FASTWRITE = %d\n", PP_FASTWRITE);
    printf("PP_FASTREAD = %d\n", PP_FASTREAD);
    printf("PP_W91284PIC = %d\n", PP_W91284PIC);

