    printf("IEEE1284_MODE_EPP = %d\n", IEEE1284_MODE_EPP);
    printf("IEEE1284_MODE_EPPSL = %d\n", IEEE1284_MODE_EPPSL);
    printf("IEEE1284_MODE_EPPSWE = %d\n", IEEE1284_MODE_EPPSWE);

    printf("\nParport control flags:\n");
    printf("PARPORT_CONTROL_STROBE = %d\n", PARPORT_CONTROL_STROBE);
    printf("PARPORT_CONTROL_AUTOFD = %d\n", PARPORT_CONTROL_AUTOFD);
    printf("PARPORT_CONTROL_INIT = %d\n", PARPORT_CONTROL_INIT);
    printf("PARPORT_CONTROL_SELECT = %d\n", PARPORT_CONTROL_SELECT);

    printf("\nParport status flags:\n");
    printf("PARPORT_STATUS_ERROR = %d\n", PARPORT_STATUS_ERROR);
    printf("PARPORT_STATUS_SELECT = %d\n", PARPORT_STATUS_SELECT);
    printf("PARPORT_STATUS_PAPEROUT = %d\n", PARPORT_STATUS_PAPEROUT);
    printf("PARPORT_STATUS_ACK = %d\n", PARPORT_STATUS_ACK);
    printf("PARPORT_STATUS_BUSY = %d\n", PARPORT_STATUS_BUSY);

    return 0;
}
EOF
